vector<int> rotateRight(vector<int> values) {
  if (values.size() < 2) {
    return values;
  }
  int lastValue = values.back();
  for (int i = values.size() - 1; i > 0; --i) {
    values[i] = values[i - 1];
  }
  values[0] = lastValue;
  return values;
}

