int countTargetSubarrays(vector<int>& values, int target) {
  unordered_map<int, int> prefixCount;
  prefixCount[0] = 1;
  int prefixSum = 0;
  int totalMatches = 0;
  for (int value : values) {
    prefixSum += value;
    int needed = prefixSum - target;
    if (prefixCount.count(needed)) {
      totalMatches += prefixCount[needed];
    }
    ++prefixCount[prefixSum];
  }
  return totalMatches;
}

vector<int> productExceptSelf(vector<int>& values) {
  vector<int> result(values.size(), 1);
  int prefix = 1;
  for (int i = 0; i < values.size(); ++i) {
    result[i] = prefix;
    prefix *= values[i];
  }
  int suffix = 1;
  for (int i = values.size() - 1; i >= 0; --i) {
    result[i] *= suffix;
    suffix *= values[i];
  }
  return result;
}

vector<vector<int>> mergeIntervals(vector<vector<int>>& intervals) {
  if (intervals.empty()) {
    return {};
  }
  sort(intervals.begin(), intervals.end());
  vector<vector<int>> merged;
  merged.push_back(intervals[0]);
  for (int i = 1; i < intervals.size(); ++i) {
    vector<int>& current = merged.back();
    if (intervals[i][0] <= current[1]) {
      current[1] = max(current[1], intervals[i][1]);
    } else {
      merged.push_back(intervals[i]);
    }
  }
  return merged;
}

