  sort(values.begin(), values.end());
  for (int i = 0; i < values.size() - 2; ++i) {
    if (i > 0 && values[i] == values[i - 1]) continue;
    int left = i + 1, right = values.size() - 1;
    while (left < right) {
      int sum = values[i] + values[left] + values[right];
      if (sum == 0) {
        result.push_back({values[i], values[left], values[right]});
        while (left < right && values[left] == values[left + 1]) ++left;
        while (left < right && values[right] == values[right - 1]) --right;
        ++left;
        --right;
      } else if (sum < 0) {
        ++left;
      } else {
        --right;
      }
    }
  }
  return result;
}

int longestUniqueSubstring(string text) {
  vector<int> lastSeen(256, -1);
  int left = 0;
  int longest = 0;
  for (int right = 0; right < text.size(); ++right) {
    unsigned char current = text[right];
    if (lastSeen[current] >= left) {
      left = lastSeen[current] + 1;
    }
    lastSeen[current] = right;
    longest = max(longest, right - left + 1);
  }
  return longest;
}

bool isValidBrackets(string text) {
  stack<char> brackets;
  for (char current : text) {
    if (current == '(' || current == '[' || current == '{') {
      brackets.push(current);
    } else {
      if (brackets.empty()) return false;
      char opening = brackets.top();
      if ((current == ')' && opening != '(') ||
          (current == ']' && opening != '[') ||
          (current == '}' && opening != '{')) {
        return false;
      }
      brackets.pop();
    }
  }
  return brackets.empty();
}

bool searchMatrix(vector<vector<int>>& matrix, int target) {
  if (matrix.empty() || matrix[0].empty()) {
    return false;
  }
  int rows = matrix.size();
  int cols = matrix[0].size();
  int left = 0;
  int right = rows * cols - 1;
  while (left <= right) {
    int middle = left + (right - left) / 2;
    int row = middle / cols;
    int col = middle % cols;
    if (matrix[row][col] == target) return true;
    if (matrix[row][col] < target) left = middle + 1;
    else right = middle - 1;
  }
  return false;
}

vector<vector<int>> generatePascal(int rows) {
  vector<vector<int>> triangle;
  for (int rowIndex = 0; rowIndex < rows; ++rowIndex) {
    vector<int> current(rowIndex + 1, 1);
    if (rowIndex > 1) {
      for (int col = 1; col < rowIndex; ++col) {
        current[col] = triangle[rowIndex - 1][col - 1] +
                       triangle[rowIndex - 1][col];
      }
    }
    triangle.push_back(current);
  }
  return triangle;
}

int longestIncreasingSubsequence(vector<int> nums) {
  int n = nums.size();
  vector<int> dp(n, 1);
  int best = 0;
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < i; ++j) {
      if (nums[j] < nums[i]) {
        dp[i] = max(dp[i], dp[j] + 1);
      }
    }
    best = max(best, dp[i]);
  }
  return best;
}

int maxProductSubarray(vector<int> nums) {
  int currentMax = nums[0];
  int currentMin = nums[0];
  int answer = nums[0];
  for (int i = 1; i < nums.size(); ++i) {
    if (nums[i] < 0) swap(currentMax, currentMin);
    currentMax = max(nums[i], currentMax * nums[i]);
    currentMin = min(nums[i], currentMin * nums[i]);
    answer = max(answer, currentMax);
  }
  return answer;
}

int coinChange(vector<int> coins, int amount) {
  vector<int> dp(amount + 1, amount + 1);
  dp[0] = 0;
  for (int current = 1; current <= amount; ++current) {
    for (int coin : coins) {
      if (coin <= current) {
        dp[current] = min(dp[current], dp[current - coin] + 1);
      }
    }
  }
  return dp[amount] > amount ? -1 : dp[amount];
}

int uniquePaths(int rows, int cols) {
  vector<vector<int>> dp(rows, vector<int>(cols, 1));
  for (int r = 1; r < rows; ++r) {
    for (int c = 1; c < cols; ++c) {
      dp[r][c] = dp[r - 1][c] + dp[r][c - 1];
    }
  }
  return dp[rows - 1][cols - 1];
}

int longestCommonSubsequence(string a, string b) {
  int n = a.size(), m = b.size();
  vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) {
      if (a[i - 1] == b[j - 1])
        dp[i][j] = dp[i - 1][j - 1] + 1;
      else
        dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
    }
  }
  return dp[n][m];
}

int editDistance(string a, string b) {
  int n = a.size(), m = b.size();
  vector<vector<int>> dp(n + 1, vector<int>(m + 1));
  for (int i = 0; i <= n; ++i) dp[i][0] = i;
  for (int j = 0; j <= m; ++j) dp[0][j] = j;
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) {
      if (a[i - 1] == b[j - 1]) dp[i][j] = dp[i - 1][j - 1];
      else dp[i][j] = 1 + min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});
    }
  }
  return dp[n][m];
}

bool hasCycle(ListNode* head) {
  ListNode* slow = head;
  ListNode* fast = head;
  while (fast != nullptr && fast->next != nullptr) {
    slow = slow->next;
    fast = fast->next->next;
    if (slow == fast) return true;
  }
  return false;
}

ListNode* cycleStart(ListNode* head) {
  ListNode* slow = head;
  ListNode* fast = head;
  while (fast && fast->next) {
    slow = slow->next;
    fast = fast->next->next;
    if (slow == fast) break;
  }
  if (!fast || !fast->next) return nullptr;
  slow = head;
  while (slow != fast) {
    slow = slow->next;
    fast = fast->next;
  }
  return slow;
}

ListNode* mergeKLists(vector<ListNode*>& lists) {
  priority_queue<ListNode*, vector<ListNode*>, Compare> pq;
  for (ListNode* node : lists) if (node) pq.push(node);
  ListNode dummy(0);
  ListNode* tail = &dummy;
  while (!pq.empty()) {
    ListNode* node = pq.top();
    pq.pop();
    tail->next = node;
    tail = node;
    if (node->next) pq.push(node->next);
  }
  return dummy.next;
}

vector<int> topKFrequent(vector<int> nums, int k) {
  unordered_map<int, int> freq;
  for (int value : nums) ++freq[value];
  vector<vector<int>> buckets(nums.size() + 1);
  for (auto& [value, count] : freq) buckets[count].push_back(value);
  vector<int> result;
  for (int count = nums.size(); count >= 1 && result.size() < k; --count) {
    for (int value : buckets[count]) {
      result.push_back(value);
      if (result.size() == k) break;
    }
  }
  return result;
}

void dfs(vector<vector<char>>& grid, int r, int c) {
  if (r < 0 || c < 0 || r >= grid.size() || c >= grid[0].size() || grid[r][c] != '1') return;
  grid[r][c] = '0';
  dfs(grid, r + 1, c);
  dfs(grid, r - 1, c);
  dfs(grid, r, c + 1);
  dfs(grid, r, c - 1);
}
int numIslands(vector<vector<char>>& grid) {
  int count = 0;
  for (int r = 0; r < grid.size(); ++r)
    for (int c = 0; c < grid[0].size(); ++c)
      if (grid[r][c] == '1') {
        ++count;
        dfs(grid, r, c);
      }
  return count;
}

Node* cloneGraph(Node* node) {
  if (!node) return nullptr;
  unordered_map<Node*, Node*> copied;
  function<Node*(Node*)> clone = [&](Node* current) {
    if (copied.count(current)) return copied[current];
    Node* copy = new Node(current->val);
    copied[current] = copy;
    for (Node* neighbor : current->neighbors)
      copy->neighbors.push_back(clone(neighbor));
    return copy;
  };
  return clone(node);
}

vector<int> courseOrder(int n, vector<vector<int>> prerequisites) {
  vector<vector<int>> graph(n);
  vector<int> indegree(n, 0);
  for (auto& pair : prerequisites) {
    graph[pair[1]].push_back(pair[0]);
    ++indegree[pair[0]];
  }
  queue<int> q;
  for (int i = 0; i < n; ++i)
    if (indegree[i] == 0) q.push(i);
  vector<int> order;
  while (!q.empty()) {
    int course = q.front();
    q.pop();
    order.push_back(course);
    for (int next : graph[course])
      if (--indegree[next] == 0) q.push(next);
  }
  return order.size() == n ? order : vector<int>{};
}

int shortestPath(vector<vector<int>>& grid) {
  int rows = grid.size(), cols = grid[0].size();
  if (grid[0][0] == 1 || grid[rows - 1][cols - 1] == 1) return -1;
  queue<pair<int, int>> q;
  vector<vector<int>> dist(rows, vector<int>(cols, -1));
  q.push({0, 0});
  dist[0][0] = 0;
  int dr[] = {1, -1, 0, 0};
  int dc[] = {0, 0, 1, -1};
  while (!q.empty()) {
    auto [r, c] = q.front(); q.pop();
    for (int d = 0; d < 4; ++d) {
      int nr = r + dr[d], nc = c + dc[d];
      if (nr >= 0 && nc >= 0 && nr < rows && nc < cols &&
          grid[nr][nc] == 0 && dist[nr][nc] == -1) {
        dist[nr][nc] = dist[r][c] + 1;
        q.push({nr, nc});
      }
    }
  }
  return dist[rows - 1][cols - 1];
}

int minMeetingRooms(vector<vector<int>> intervals) {
  vector<int> starts, ends;
  for (auto& meeting : intervals) {
    starts.push_back(meeting[0]);
    ends.push_back(meeting[1]);
  }
  sort(starts.begin(), starts.end());
  sort(ends.begin(), ends.end());
  int rooms = 0, endIndex = 0;
  for (int start : starts) {
    if (start < ends[endIndex]) ++rooms;
    else ++endIndex;
  }
  return rooms;
}

int maxProfit(vector<int> prices) {
  int profit = 0;
  for (int i = 1; i < prices.size(); ++i) {
    if (prices[i] > prices[i - 1])
      profit += prices[i] - prices[i - 1];
  }
  return profit;
}

int largestRectangleArea(vector<int> heights) {
  stack<int> st;
  heights.push_back(0);
  int best = 0;
  for (int i = 0; i < heights.size(); ++i) {
    while (!st.empty() && heights[st.top()] > heights[i]) {
      int height = heights[st.top()];
      st.pop();
      int left = st.empty() ? -1 : st.top();
      best = max(best, height * (i - left - 1));
    }
    st.push(i);
  }
  return best;
}

string serialize(TreeNode* root) {
  if (!root) return "#";
  return to_string(root->val) + "," + serialize(root->left) + "," + serialize(root->right);
}

TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
  if (!root || root == p || root == q) return root;
  TreeNode* left = lowestCommonAncestor(root->left, p, q);
  TreeNode* right = lowestCommonAncestor(root->right, p, q);
  if (left && right) return root;
  return left ? left : right;
}

bool searchWord(vector<vector<char>>& board, string word, int r, int c, int index) {
  if (index == word.size()) return true;
  if (r < 0 || c < 0 || r >= board.size() || c >= board[0].size() || board[r][c] != word[index]) return false;
  char saved = board[r][c];
  board[r][c] = '#';
  bool found = searchWord(board, word, r + 1, c, index + 1) ||
               searchWord(board, word, r - 1, c, index + 1) ||
               searchWord(board, word, r, c + 1, index + 1) ||
               searchWord(board, word, r, c - 1, index + 1);
  board[r][c] = saved;
  return found;
}
bool exist(vector<vector<char>>& board, string word) {
  for (int r = 0; r < board.size(); ++r)
    for (int c = 0; c < board[0].size(); ++c)
      if (searchWord(board, word, r, c, 0)) return true;
  return false;
}
